const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get order details
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = 'ORD-E0E671'\").get();
console.log('=== ORDER ===');
console.log(JSON.stringify(order, null, 2));

// Get order items
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-E0E671'\").all();
console.log('\n=== ORDER ITEMS ===');
console.log(JSON.stringify(items, null, 2));

// Get user info
if (order) {
  const user = db.prepare('SELECT * FROM users WHERE user_id = ?').get(order.user_id);
  console.log('\n=== USER ===');
  console.log(JSON.stringify(user, null, 2));
}

// Get product details for items
for (const item of items) {
  if (item.product_id) {
    const product = db.prepare('SELECT * FROM products WHERE product_id = ?').get(item.product_id);
    console.log('\n=== PRODUCT:', item.product_id, '===');
    console.log(JSON.stringify(product, null, 2));
  }
  if (item.variant_id) {
    const variant = db.prepare('SELECT * FROM rt_variants WHERE variant_id = ?').get(item.variant_id);
    console.log('=== VARIANT:', item.variant_id, '===');
    console.log(JSON.stringify(variant, null, 2));
  }
}

// Fulfillment & payment
const fulfillments = db.prepare(\"SELECT * FROM order_fulfillments WHERE order_id = 'ORD-E0E671'\").all();
console.log('\n=== FULFILLMENTS ===');
console.log(JSON.stringify(fulfillments, null, 2));

const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = 'ORD-E0E671'\").all();
console.log('\n=== PAYMENTS ===');
console.log(JSON.stringify(payments, null, 2));
"

