node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const cartId = 'CART-user_be7538d5';
const customerId = 'user_be7538d5';
const productId = 'PROD-73FAB4';
const newItemId = 'CI-0032';
const lampPrice = 88;

// Insert new cart item
db.prepare(\`
  INSERT INTO cart_items (cart_item_id, cart_id, customer_id, product_id, quantity, gift_wrap, variant_id)
  VALUES (?, ?, ?, ?, 1, 0, NULL)
\`).run(newItemId, cartId, customerId, productId);

// Update cart totals and item list
const newSubtotal = 62 + lampPrice;  // 150
const newTotal = newSubtotal + 6;     // 156 (keeping existing shipping cost)
const newItemIds = JSON.stringify(['CI-0024', 'CI-0025', newItemId]);

db.prepare(\`
  UPDATE carts 
  SET subtotal = ?, total = ?, item_ids_json = ?
  WHERE cart_id = ?
\`).run(newSubtotal, newTotal, newItemIds, cartId);

// Verify
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);
const items = db.prepare('SELECT * FROM cart_items WHERE cart_id = ?').all(cartId);
console.log('UPDATED CART:', JSON.stringify(cart, null, 2));
console.log('ALL CART ITEMS:', JSON.stringify(items, null, 2));
"

